#include "lru.h"

#include <errno.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#define NIL UINT32_MAX
#define INITIAL_POOL 64u

typedef struct {
    lru_str key;
    lru_str value;
    uint64_t hash;
    uint32_t prev, next; /* recency list; head = most recently used */
    uint32_t chain;      /* next node in the same bucket, or free-list link */
} node;

struct lru_cache {
    node *nodes;
    uint32_t *buckets;
    size_t bucket_mask;
    size_t capacity;
    size_t size;
    uint32_t pool_len; /* nodes ever handed out from the pool */
    uint32_t pool_cap; /* nodes allocated */
    uint32_t free_list;
    uint32_t head, tail;
};

static uint64_t hash_bytes(const char *p, size_t n)
{
    uint64_t h = 0xcbf29ce484222325u; /* FNV-1a */
    for (size_t i = 0; i < n; i++) {
        h ^= (unsigned char)p[i];
        h *= 0x100000001b3u;
    }
    /* Final avalanche so the low bits used for bucketing are well mixed. */
    h ^= h >> 33;
    h *= 0xff51afd7ed558ccdu;
    h ^= h >> 33;
    return h;
}

static size_t bucket_count_for(size_t nodes)
{
    size_t n = 1;
    while (n < nodes * 2)
        n <<= 1;
    return n;
}

static int rebuild_buckets(lru_cache *c, size_t nbuckets)
{
    uint32_t *b = malloc(nbuckets * sizeof *b);
    if (!b)
        return ENOMEM;
    for (size_t i = 0; i < nbuckets; i++)
        b[i] = NIL;
    for (uint32_t i = c->head; i != NIL; i = c->nodes[i].next) {
        uint32_t *slot = &b[c->nodes[i].hash & (nbuckets - 1)];
        c->nodes[i].chain = *slot;
        *slot = i;
    }
    free(c->buckets);
    c->buckets = b;
    c->bucket_mask = nbuckets - 1;
    return 0;
}

/* Grow the node pool (never beyond capacity), rehashing as needed. */
static int grow(lru_cache *c)
{
    size_t ncap = (size_t)c->pool_cap * 2;
    if (ncap > c->capacity)
        ncap = c->capacity;
    node *n = realloc(c->nodes, ncap * sizeof *n);
    if (!n)
        return ENOMEM;
    c->nodes = n;
    size_t nbuckets = bucket_count_for(ncap);
    if (nbuckets > c->bucket_mask + 1) {
        int err = rebuild_buckets(c, nbuckets);
        if (err)
            return err; /* larger pool with old buckets is still valid */
    }
    c->pool_cap = (uint32_t)ncap;
    return 0;
}

lru_cache *lru_create(size_t capacity)
{
    if (capacity == 0 || capacity >= NIL)
        return NULL;

    lru_cache *c = malloc(sizeof *c);
    if (!c)
        return NULL;
    size_t pool = capacity < INITIAL_POOL ? capacity : INITIAL_POOL;
    size_t nbuckets = bucket_count_for(pool);
    c->nodes = malloc(pool * sizeof *c->nodes);
    c->buckets = malloc(nbuckets * sizeof *c->buckets);
    if (!c->nodes || !c->buckets) {
        lru_destroy(c);
        return NULL;
    }
    for (size_t i = 0; i < nbuckets; i++)
        c->buckets[i] = NIL;

    c->bucket_mask = nbuckets - 1;
    c->capacity = capacity;
    c->size = 0;
    c->pool_len = 0;
    c->pool_cap = (uint32_t)pool;
    c->free_list = NIL;
    c->head = c->tail = NIL;
    return c;
}

void lru_destroy(lru_cache *c)
{
    if (!c)
        return;
    free(c->nodes);
    free(c->buckets);
    free(c);
}

size_t lru_size(const lru_cache *c)
{
    return c->size;
}

static inline bool key_eq(const node *n, uint64_t hash, lru_str key)
{
    return n->hash == hash && n->key.len == key.len &&
           memcmp(n->key.data, key.data, key.len) == 0;
}

/* Return the link that refers to the node holding `key` (a bucket slot or a
 * predecessor's chain field); it holds NIL if the key is absent. */
static uint32_t *find_link(lru_cache *c, uint64_t hash, lru_str key)
{
    uint32_t *link = &c->buckets[hash & c->bucket_mask];
    while (*link != NIL && !key_eq(&c->nodes[*link], hash, key))
        link = &c->nodes[*link].chain;
    return link;
}

static void list_unlink(lru_cache *c, uint32_t i)
{
    node *n = &c->nodes[i];
    if (n->prev != NIL)
        c->nodes[n->prev].next = n->next;
    else
        c->head = n->next;
    if (n->next != NIL)
        c->nodes[n->next].prev = n->prev;
    else
        c->tail = n->prev;
}

static void list_push_front(lru_cache *c, uint32_t i)
{
    node *n = &c->nodes[i];
    n->prev = NIL;
    n->next = c->head;
    if (c->head != NIL)
        c->nodes[c->head].prev = i;
    else
        c->tail = i;
    c->head = i;
}

static void touch(lru_cache *c, uint32_t i)
{
    if (c->head == i)
        return;
    list_unlink(c, i);
    list_push_front(c, i);
}

/* Detach node `i`, reached via `link`, from its bucket and the recency list,
 * and return it to the free list. */
static void remove_node(lru_cache *c, uint32_t *link, uint32_t i)
{
    *link = c->nodes[i].chain;
    list_unlink(c, i);
    c->nodes[i].chain = c->free_list;
    c->free_list = i;
    c->size--;
}

static void evict_lru(lru_cache *c)
{
    uint32_t victim = c->tail;
    uint32_t *link = &c->buckets[c->nodes[victim].hash & c->bucket_mask];
    while (*link != victim)
        link = &c->nodes[*link].chain;
    remove_node(c, link, victim);
}

int lru_set(lru_cache *c, lru_str key, lru_str value)
{
    uint64_t hash = hash_bytes(key.data, key.len);
    uint32_t *link = find_link(c, hash, key);
    if (*link != NIL) {
        c->nodes[*link].value = value;
        touch(c, *link);
        return 0;
    }

    uint32_t i;
    if (c->size == c->capacity) {
        evict_lru(c);
        i = c->free_list;
        c->free_list = c->nodes[i].chain;
    } else if (c->free_list != NIL) {
        i = c->free_list;
        c->free_list = c->nodes[i].chain;
    } else {
        if (c->pool_len == c->pool_cap) {
            int err = grow(c);
            if (err)
                return err;
        }
        i = c->pool_len++;
    }

    node *n = &c->nodes[i];
    n->key = key;
    n->value = value;
    n->hash = hash;
    /* Eviction or rehashing may have changed the bucket; look it up afresh. */
    uint32_t *bucket = &c->buckets[hash & c->bucket_mask];
    n->chain = *bucket;
    *bucket = i;
    list_push_front(c, i);
    c->size++;
    return 0;
}

bool lru_get(lru_cache *c, lru_str key, lru_str *out)
{
    uint64_t hash = hash_bytes(key.data, key.len);
    uint32_t i = *find_link(c, hash, key);
    if (i == NIL)
        return false;
    touch(c, i);
    *out = c->nodes[i].value;
    return true;
}

bool lru_del(lru_cache *c, lru_str key)
{
    uint64_t hash = hash_bytes(key.data, key.len);
    uint32_t *link = find_link(c, hash, key);
    if (*link == NIL)
        return false;
    remove_node(c, link, *link);
    return true;
}

#ifndef LRU_LRU_H
#define LRU_LRU_H

#include <stdbool.h>
#include <stddef.h>

/*
 * Fixed-capacity LRU cache mapping byte-string keys to byte-string values.
 *
 * The cache does not copy keys or values: it stores views into memory owned
 * by the caller, which must stay valid and unchanged for as long as the
 * cache may reference them (until the entry is overwritten, deleted, evicted
 * or the cache is destroyed).
 *
 * All operations run in O(1) expected time.
 */

typedef struct lru_cache lru_cache;

typedef struct {
    const char *data;
    size_t len;
} lru_str;

/*
 * Create a cache holding at most `capacity` keys (1 <= capacity < 2^32 - 1).
 * Storage grows on demand. Returns NULL on invalid capacity or allocation
 * failure.
 */
lru_cache *lru_create(size_t capacity);
void lru_destroy(lru_cache *c);

/* Insert or overwrite; the key becomes most recently used. Evicts the least
 * recently used key if the cache would exceed its capacity. Returns 0, or
 * ENOMEM if storage could not grow (the cache is left unchanged). */
int lru_set(lru_cache *c, lru_str key, lru_str value);

/* On hit, store the value in *out, mark the key most recently used and
 * return true. */
bool lru_get(lru_cache *c, lru_str key, lru_str *out);

/* Remove the key; returns true if it was present. */
bool lru_del(lru_cache *c, lru_str key);

size_t lru_size(const lru_cache *c);

#endif

/* lru: simulate an LRU cache driven by commands on standard input. */
#include "lru.h"

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define CAPACITY_MAX 1000000u

typedef struct {
    char *data;
    size_t len;
} buffer;

static int read_all(FILE *in, buffer *out)
{
    size_t cap = 1 << 16, len = 0;
    char *data = malloc(cap);
    if (!data)
        return ENOMEM;
    for (;;) {
        if (len == cap) {
            if (cap > SIZE_MAX / 2) {
                free(data);
                return ENOMEM;
            }
            char *p = realloc(data, cap * 2);
            if (!p) {
                free(data);
                return ENOMEM;
            }
            data = p;
            cap *= 2;
        }
        size_t n = fread(data + len, 1, cap - len, in);
        len += n;
        if (n == 0) {
            if (ferror(in)) {
                free(data);
                return EIO;
            }
            break;
        }
    }
    out->data = data;
    out->len = len;
    return 0;
}

/* Buffered stdout writer. */
typedef struct {
    char buf[1 << 16];
    size_t len;
    FILE *f;
} writer;

static void w_flush(writer *w)
{
    if (w->len)
        fwrite(w->buf, 1, w->len, w->f);
    w->len = 0;
}

static void w_line(writer *w, const char *s, size_t n)
{
    if (sizeof w->buf - w->len < n + 1)
        w_flush(w);
    memcpy(w->buf + w->len, s, n);
    w->len += n;
    w->buf[w->len++] = '\n';
}

static void w_size(writer *w, size_t v)
{
    char tmp[24];
    int n = snprintf(tmp, sizeof tmp, "%zu", v);
    w_line(w, tmp, (size_t)n);
}

/* Split off the next space-delimited token from *rest (within a line). */
static lru_str next_token(lru_str *rest)
{
    const char *p = rest->data;
    const char *sp = memchr(p, ' ', rest->len);
    size_t n = sp ? (size_t)(sp - p) : rest->len;
    lru_str tok = {p, n};
    rest->data = p + (sp ? n + 1 : n);
    rest->len -= sp ? n + 1 : n;
    return tok;
}

static bool tok_is(lru_str t, const char *lit)
{
    size_t n = strlen(lit);
    return t.len == n && memcmp(t.data, lit, n) == 0;
}

static bool parse_capacity(lru_str s, size_t *out)
{
    size_t v = 0;
    if (s.len == 0)
        return false;
    for (size_t i = 0; i < s.len; i++) {
        unsigned d = (unsigned char)s.data[i] - '0';
        if (d > 9)
            return false;
        v = v * 10 + d;
        if (v > CAPACITY_MAX)
            return false;
    }
    if (v == 0)
        return false;
    *out = v;
    return true;
}

/* Fetch the next line from the input, without its terminator (and a trailing
 * CR, if any). Returns false at end of input. */
static bool next_line(const buffer *in, size_t *pos, lru_str *line)
{
    if (*pos >= in->len)
        return false;
    const char *start = in->data + *pos;
    size_t avail = in->len - *pos;
    const char *nl = memchr(start, '\n', avail);
    size_t n = nl ? (size_t)(nl - start) : avail;
    *pos += nl ? n + 1 : n;
    if (n && start[n - 1] == '\r')
        n--;
    *line = (lru_str){start, n};
    return true;
}

int main(void)
{
    buffer in;
    int err = read_all(stdin, &in);
    if (err) {
        fprintf(stderr, "lru: reading input: %s\n", strerror(err));
        return EXIT_FAILURE;
    }

    size_t pos = 0, capacity;
    lru_str line;
    if (!next_line(&in, &pos, &line) || !parse_capacity(line, &capacity)) {
        fprintf(stderr, "lru: first line must be a capacity in 1..%u\n", CAPACITY_MAX);
        free(in.data);
        return EXIT_FAILURE;
    }

    lru_cache *cache = lru_create(capacity);
    if (!cache) {
        fprintf(stderr, "lru: out of memory\n");
        free(in.data);
        return EXIT_FAILURE;
    }

    static writer out;
    out.f = stdout;
    int status = EXIT_SUCCESS;

    while (next_line(&in, &pos, &line)) {
        lru_str rest = line;
        lru_str cmd = next_token(&rest);
        if (tok_is(cmd, "SET")) {
            lru_str key = next_token(&rest);
            lru_str value = next_token(&rest);
            if (lru_set(cache, key, value) != 0) {
                fprintf(stderr, "lru: out of memory\n");
                status = EXIT_FAILURE;
                break;
            }
        } else if (tok_is(cmd, "GET")) {
            lru_str value;
            if (lru_get(cache, next_token(&rest), &value))
                w_line(&out, value.data, value.len);
            else
                w_line(&out, "NULL", 4);
        } else if (tok_is(cmd, "DEL")) {
            w_line(&out, lru_del(cache, next_token(&rest)) ? "1" : "0", 1);
        } else if (tok_is(cmd, "SIZE")) {
            w_size(&out, lru_size(cache));
        }
        /* Blank or unrecognised lines are ignored. */
    }

    w_flush(&out);
    if (fflush(stdout) != 0 || ferror(stdout))
        status = EXIT_FAILURE;
    lru_destroy(cache);
    free(in.data);
    return status;
}
